const https = require("https");
const http = require("http");
const crypto = require("crypto");

const env = $env || {};
const envelope = $json.envelope;
const body = envelope.body;
const candidate = body.candidate;
const target = body.target;
const assets = body.assets || [];
const asset = assets[0] || null;

function httpReq(method, url, { headers = {}, multipart = false, formData = {}, binary = null } = {}) {
  return new Promise((resolve, reject) => {
    const finalHeaders = { ...headers };
    let payload = null;

    if (multipart) {
      const boundary = "----mmboundary" + crypto.randomBytes(16).toString("hex");
      finalHeaders["Content-Type"] = "multipart/form-data; boundary=" + boundary;
      const chunks = [];
      for (const [key, value] of Object.entries(formData)) {
        chunks.push(Buffer.from(
          "--" + boundary + "\r\n" +
          "Content-Disposition: form-data; name=\"" + key + "\"\r\n\r\n" +
          String(value) + "\r\n",
          "utf8",
        ));
      }
      chunks.push(Buffer.from(
        "--" + boundary + "\r\n" +
        "Content-Disposition: form-data; name=\"source\"; filename=\"asset\"\r\n" +
        "Content-Type: " + asset.mime_type + "\r\n\r\n",
        "utf8",
      ));
      chunks.push(binary);
      chunks.push(Buffer.from("\r\n--" + boundary + "--\r\n", "utf8"));
      payload = Buffer.concat(chunks);
      finalHeaders["Content-Length"] = String(payload.length);
    }

    const lib = url.startsWith("https:") ? https : http;
    const req = lib.request(url, { method, headers: finalHeaders }, (res) => {
      const chunks = [];
      res.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
      res.on("end", () => {
        const buffer = Buffer.concat(chunks);
        resolve({
          status: Number(res.statusCode || 0),
          headers: res.headers || {},
          body: buffer.toString("utf8"),
          buf: buffer,
        });
      });
    });
    req.on("error", reject);
    req.setTimeout(15000, () => {
      const timeout = new Error("request timed out");
      timeout.code = "ETIMEDOUT";
      req.destroy(timeout);
    });
